// src/App.tsx - Interactive Tic Tac Toe Game
// Generated by Coalesce SDLC Engine for CUSTOM-WIDG

import React, { useState, useEffect } from 'react';

export default function TicTacToe() {
  const [board, setBoard] = useState<Array<string | null>>(Array(9).fill(null));
  const [isXNext, setIsXNext] = useState<boolean>(true);
  const [scores, setScores] = useState<{ x: number; o: number }>({ x: 0, o: 0 });
  const [darkMode, setDarkMode] = useState<boolean>(true);

  const calculateWinner = (squares: Array<string | null>) => {
    const lines = [
      [0, 1, 2], [3, 4, 5], [6, 7, 8],
      [0, 3, 6], [1, 4, 7], [2, 5, 8],
      [0, 4, 8], [2, 4, 6]
    ];
    for (const [a, b, c] of lines) {
      if (squares[a] && squares[a] === squares[b] && squares[a] === squares[c]) {
        return { winner: squares[a], line: [a, b, c] };
      }
    }
    return null;
  };

  const winInfo = calculateWinner(board);
  const isDraw = !winInfo && board.every((cell) => cell !== null);

  const handleCellClick = (index: number) => {
    if (board[index] || winInfo) return;
    const nextBoard = [...board];
    const currentSymbol = isXNext ? 'X' : 'O';
    nextBoard[index] = currentSymbol;
    setBoard(nextBoard);

    const winner = calculateWinner(nextBoard);
    if (winner) {
      if (winner.winner === 'X') {
        setScores((prev) => ({ ...prev, x: prev.x + 1 }));
      } else {
        setScores((prev) => ({ ...prev, o: prev.o + 1 }));
      }
    } else {
      setIsXNext(!isXNext);
    }
  };

  const handleNewGame = () => {
    setBoard(Array(9).fill(null));
    setIsXNext(true);
  };

  const handleResetScores = () => {
    setScores({ x: 0, o: 0 });
    handleNewGame();
  };

  return (
    <div className={darkMode ? 'game-container dark' : 'game-container light'}>
      <header className="game-header">
        <h1>Tic Tac Toe</h1>
        <p>The classic X and O game</p>
        <button className="theme-toggle" onClick={() => setDarkMode(!darkMode)}>
          {darkMode ? '🌙' : '☀️'}
        </button>
      </header>

      <div className="scoreboard">
        <div className="score-badge x-score">
          <span className="player-icon">❌</span> Player X: <strong>{scores.x}</strong>
        </div>
        <div className="score-badge o-score">
          <span className="player-icon">⭕</span> Player O: <strong>{scores.o}</strong>
        </div>
      </div>

      <div className="status-banner">
        {winInfo ? (
          <span className="win-text">🎉 Player {winInfo.winner} Wins!</span>
        ) : isDraw ? (
          <span className="draw-text">🤝 It's a Draw!</span>
        ) : (
          <span>Player <strong>{isXNext ? 'X' : 'O'}</strong>'s turn</span>
        )}
      </div>

      <div className="board-grid">
        {board.map((cell, idx) => {
          const isWinningCell = winInfo?.line.includes(idx);
          return (
            <button
              key={idx}
              className={`cell ${isWinningCell ? 'winning-cell' : ''} ${cell ? cell.toLowerCase() : ''}`}
              onClick={() => handleCellClick(idx)}
            >
              {cell === 'X' ? '✕' : cell === 'O' ? '○' : ''}
            </button>
          );
        })}
      </div>

      <div className="game-actions">
        <button className="btn-action primary" onClick={handleNewGame}>New Game</button>
        <button className="btn-action secondary" onClick={handleResetScores}>Reset Scores</button>
      </div>
    </div>
  );
}
